                    "sql": "create or replace table maplemonk.easyecom_tax_sales_data as select case when coalesce(c.final_marketplace,upper(b.mp_name)) like \'%AMAZON%\' then \'AMAZON\' else upper(coalesce(c.final_marketplace,b.mp_name)) end as marketplace, coalesce(c.FINAL_UTM_CHANNEL,case when upper(b.mp_name) like \'%AMAZON%\' then \'AMAZON\' else upper(b.mp_name) end) as marketing_channel, date(b.invoice_date) as date, case when upper(coalesce(c.brand,b.component_sku_brand)) like \'%DB%\' then \'DREAM BEAUTY\' else upper(coalesce(c.brand,b.component_sku_brand)) end as brand, upper(coalesce(s.sub_category,p.product_sub_category)) as sub_category, case when upper(coalesce(c.final_marketplace,b.mp_name)) like \'%B2B%\' then \'B2B\' when upper(coalesce(c.final_marketplace,b.mp_name)) like \'%SHOPIFY%\' then \'D2C\' else \'B2C\' end as Channel_type, ifnull(sum(ifnull(cast(b.taxable_value as float64),0)),0) total_sales_excl_cancl, 0 as return_value from maplemonk.easyecom_pharma_tax_sales b left join (select * from ( select * ,\'SHOPIFY - DB\' as final_marketplace ,\'SHOPIFY - DB\' as MP_Name ,Upper(FINAL_UTM_CHANNEL) AS CHANNEL ,\'DREAM BEAUTY\' AS Brand ,row_number()over(partition by order_name, LINE_ITEM_ID order by date(order_timestamp) desc) rw from thd-pharma-wh.MAPLEMONK.thd_pharma_wh_SHOPIFY_FACT_ITEMS union all select * ,\'SHOPIFY - OZONEAYURVEDICS\' as final_marketplace ,\'SHOPIFY - OZONEAYURVEDICS\' as MP_Name ,Upper(FINAL_UTM_CHANNEL) AS CHANNEL ,\'OZONE\' AS Brand ,row_number()over(partition by order_name, LINE_ITEM_ID order by date(order_timestamp) desc) rw from thd-pharma-wh.MAPLEMONK.thd_pharma_wh_SHOPIFY_OzoneAyurvedics_FACT_ITEMS union all select * ,\'SHOPIFY - OZONE SIGNATURE\' as final_marketplace ,\'SHOPIFY - OZONE SIGNATURE\' as MP_Name ,Upper(FINAL_UTM_CHANNEL) AS CHANNEL ,\'OZONE\' AS Brand ,row_number()over(partition by order_name, LINE_ITEM_ID order by date(order_timestamp) desc) rw from thd-pharma-wh.MAPLEMONK.thd_pharma_wh_SHOPIFY_Ozone_Signature_FACT_ITEMS ) z where z.rw = 1 ) c on replace(c.order_name,\'#\',\'\') = b.reference_code and c.LINE_ITEM_ID=replace(b.suborder_no,\'`\',\'\') left join (select Master_sku, Product_name, Brand, Style, Product_category, Product_sub_category, Nature from `MAPLEMONK.final_SKU_MASTER` qualify row_number() over (partition by master_sku order by master_sku) = 1 ) p on lower(replace(b.Component_SKU,\'`\',\'\')) = lower(p.Master_sku) left join (select commonsku, sub_category from `MAPLEMONK.ozone_pharma_sku_master` qualify row_number() over (partition by upper(commonsku) order by commonsku) = 1) s on lower(replace(b.Component_SKU,\'`\',\'\')) = lower(s.commonsku) where upper(b.order_type) <> \'STN\' and upper(b.mp_name) <> \'OFFLINE\' and not(upper(b.mp_name) like \'%B2B%\' and b.customer_name like any (\'Concepto Communications LLP | Moodboard PR\',\'Moodboard pr agency\')) group by 1,2,3,4,5,6 ; create or replace table maplemonk.easyecom_tax_returns_data as select case when coalesce(c.final_marketplace,upper(b.mp_name)) like \'%AMAZON%\' then \'AMAZON\' else upper(coalesce(c.final_marketplace,b.mp_name)) end as marketplace, coalesce(c.FINAL_UTM_CHANNEL,case when upper(b.mp_name) like \'%AMAZON%\' then \'AMAZON\' else upper(b.mp_name) end) as marketing_channel, date(b.return_date) as date, case when upper(coalesce(c.brand,b.component_sku_brand)) like \'%DB%\' then \'DREAM BEAUTY\' else upper(coalesce(c.brand,b.component_sku_brand)) end as brand, upper(coalesce(s.sub_category,p.product_sub_category)) as sub_category, case when upper(coalesce(c.final_marketplace,b.mp_name)) like \'%B2B%\' then \'B2B\' when upper(coalesce(c.final_marketplace,b.mp_name)) like \'%SHOPIFY%\' then \'D2C\' else \'B2C\' end as Channel_type, 0 as total_sales, sum(ifnull(cast(taxable_value as float64),0)) as return_value from maplemonk.easyecom_pharma_tax_returns b left join (select * from ( select * ,\'SHOPIFY - DB\' as final_marketplace ,\'SHOPIFY - DB\' as MP_Name ,Upper(FINAL_UTM_CHANNEL) AS CHANNEL ,\'DREAM BEAUTY\' AS Brand ,row_number()over(partition by order_name, LINE_ITEM_ID order by date(order_timestamp) desc) rw from thd-pharma-wh.MAPLEMONK.thd_pharma_wh_SHOPIFY_FACT_ITEMS union all select * ,\'SHOPIFY - OZONEAYURVEDICS\' as final_marketplace ,\'SHOPIFY - OZONEAYURVEDICS\' as MP_Name ,Upper(FINAL_UTM_CHANNEL) AS CHANNEL ,\'OZONE\' AS Brand ,row_number()over(partition by order_name, LINE_ITEM_ID order by date(order_timestamp) desc) rw from thd-pharma-wh.MAPLEMONK.thd_pharma_wh_SHOPIFY_OzoneAyurvedics_FACT_ITEMS union all select * ,\'SHOPIFY - OZONE SIGNATURE\' as final_marketplace ,\'SHOPIFY - OZONE SIGNATURE\' as MP_Name ,Upper(FINAL_UTM_CHANNEL) AS CHANNEL ,\'OZONE\' AS Brand ,row_number()over(partition by order_name, LINE_ITEM_ID order by date(order_timestamp) desc) rw from thd-pharma-wh.MAPLEMONK.thd_pharma_wh_SHOPIFY_Ozone_Signature_FACT_ITEMS ) z where z.rw = 1 ) c on replace(c.order_name,\'#\',\'\') = b.reference_code and c.LINE_ITEM_ID=replace(b.suborder_no,\'`\',\'\') left join (select Master_sku, Product_name, Brand, Style, Product_category, Product_sub_category, Nature from `MAPLEMONK.final_SKU_MASTER` qualify row_number() over (partition by master_sku order by master_sku) = 1 ) p on lower(replace(b.Component_SKU,\'`\',\'\')) = lower(p.Master_sku) left join (select commonsku, sub_category from `MAPLEMONK.ozone_pharma_sku_master` qualify row_number() over (partition by upper(commonsku) order by commonsku) = 1) s on lower(replace(b.Component_SKU,\'`\',\'\')) = lower(s.commonsku) where upper(b.order_type) <> \'STN\' and upper(b.mp_name) <> \'OFFLINE\' and not(upper(b.mp_name) like \'%B2B%\' and b.customer_name like any (\'Concepto Communications LLP | Moodboard PR\',\'Moodboard pr agency\')) group by 1,2,3,4,5,6; create or replace table thd-pharma-wh.MAPLEMONK.summary_dashboard_table_intermediate as WITH easyecom_sales_data as ( SELECT marketplace, marketing_channel, date, brand, sub_category, channel_type, SUM(total_sales_excl_cancl) AS total_sales_excl_cancl, SUM(return_value) AS return_value FROM ( SELECT marketplace, marketing_channel, date, brand, sub_category, channel_type, total_sales_excl_cancl, return_value FROM maplemonk.easyecom_tax_sales_data UNION ALL SELECT marketplace, marketing_channel, date, brand, sub_category, channel_type, total_sales AS total_sales_excl_cancl, return_value FROM maplemonk.easyecom_tax_returns_data ) GROUP BY 1, 2, 3, 4, 5, 6 ), spendd2c as (select date ,case when lower(channel) like \'%facebook%\' and lower(brand) like \'%db%\' then \'SHOPIFY - DB\' when lower(channel) like \'%google ads - db%\' then \'SHOPIFY - DB\' when lower(channel) like \'%facebook%\' and lower(brand) like \'%ozone%\' then \'SHOPIFY - OZONEAYURVEDICS\' when lower(channel) like \'%google ads - ozone%\' then \'SHOPIFY - OZONEAYURVEDICS\' when lower(channel) like \'%amazon%\' then \'AMAZON\' when lower(channel) like \'%flipkart%\' then \'FLIPKART\' when lower(channel) like \'%myntra%\' then \'MYNTRA\' else upper(channel) end as Marketplace ,upper(channel) marketing_Channel ,Case When lower(BRAND) like \'%db%\' or lower(BRAND) like \'%dream%\' then \'DREAM BEAUTY\' When lower(Brand) like \'%ozone%\' then \'OZONE\' End as Brand ,sum(ifnull(spend,0)) as spend ,sum(ifnull(impressions,0)) as ad_impressions ,sum(ifnull(clicks,0)) as ad_clicks ,sum(ifnull(conversions,0)) as ad_conversions ,sum(ifnull(conversion_value,0)) as ad_sales from thd-pharma-wh.MAPLEMONK.thd_pharma_wh_MARKETING_CONSOLIDATED group by 1,2,3,4 ), sales_and_ads_data as ( select coalesce(e.Date,MC.date) as date, upper(coalesce(e.marketplace,MC.marketplace)) as Marketplace, upper(coalesce(e.marketing_channel,MC.marketing_Channel)) as Marketing_Channel, upper(coalesce(e.brand, mc.brand)) as Brand, Case when upper(coalesce(e.marketplace,MC.marketplace)) like \'%B2B%\' then \'B2B\' when upper(coalesce(e.marketplace,MC.marketplace)) like \'%SHOPIFY%\' then \'D2C\' else \'B2C\' end as Channel_type, e.sub_category, e.total_sales_excl_cancl, e.return_value, mc.spend as marketing_spend from easyecom_sales_data e full outer join spendd2c MC on e.Date = MC.date and lower(e.marketing_channel)=lower(MC.marketing_channel) and lower(e.Marketplace)=lower(MC.Marketplace) and lower(e.brand) = lower(mc.brand) ),date_spine AS ( SELECT date_spine_col AS date FROM UNNEST( GENERATE_DATE_ARRAY( (SELECT MIN(date) FROM sales_and_ads_data), CURRENT_DATE() - 1, INTERVAL 1 DAY ) ) AS date_spine_col ), unique_dims AS ( SELECT DISTINCT Marketplace, Marketing_Channel, Brand, Channel_type, sub_category FROM sales_and_ads_data WHERE Marketplace IS NOT NULL ), master_spine AS ( SELECT d.date, u.* FROM date_spine d CROSS JOIN unique_dims u ), base AS ( SELECT m.date, m.Marketplace, m.Marketing_Channel, m.Brand, m.Channel_type, m.sub_category, COALESCE(s.total_sales_excl_cancl, 0) AS total_sales_excl_cancl, COALESCE(s.return_value, 0) AS return_value, COALESCE(s.marketing_spend, 0) AS marketing_spend, CASE WHEN EXTRACT(MONTH FROM m.date) >= 4 THEN EXTRACT(YEAR FROM m.date) ELSE EXTRACT(YEAR FROM m.date) - 1 END AS fy_start_year FROM master_spine m LEFT JOIN sales_and_ads_data s ON m.date = s.date AND COALESCE(m.Marketplace, \'\') = COALESCE(s.Marketplace, \'\') AND COALESCE(m.Marketing_Channel, \'\') = COALESCE(s.Marketing_Channel, \'\') AND COALESCE(m.Brand, \'\') = COALESCE(s.Brand, \'\') AND COALESCE(m.Channel_type, \'\') = COALESCE(s.Channel_type, \'\') AND COALESCE(m.sub_category, \'\') = COALESCE(s.sub_category, \'\') ) select date, marketplace, channel_type, marketing_channel, brand, sub_category, ifnull(total_sales_excl_cancl,0) - ifnull(return_value,0) sales, sum(ifnull(total_sales_excl_cancl,0) - ifnull(return_value,0)) over (partition by marketing_channel, marketplace, brand, channel_type, sub_category, date_trunc(date, month) order by date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) mtd_sales, sum(ifnull(total_sales_excl_cancl,0) - ifnull(return_value,0)) OVER (PARTITION BY marketing_channel, marketplace, brand, channel_type, sub_category, fy_start_year ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS fy_ytd_sales, ifnull(marketing_spend,0) as marketing_spend, sum(ifnull(marketing_spend,0)) over (partition by marketing_channel, marketplace, brand, channel_type, sub_category, date_trunc(date, month) order by date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) mtd_spend, sum(ifnull(marketing_spend,0)) OVER (PARTITION BY marketing_channel, marketplace, brand, channel_type, sub_category, fy_start_year ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS fy_ytd_spend from base ; CREATE OR REPLACE TABLE thd-pharma-wh.MAPLEMONK.summary_dashboard_table AS WITH target_summary AS ( SELECT UPPER(channel) AS channel, UPPER(brand) AS brand, AVG(sales_target) AS sales_target, AVG(spends_target) AS spends_target FROM thd-pharma-wh.maplemonk.channel_targets GROUP BY 1, 2 ), unid_data AS ( SELECT date, marketplace, channel_type, marketing_channel, brand, sub_category, sales, mtd_sales, fy_ytd_sales, marketing_Spend, mtd_spend, fy_ytd_spend, 0 AS previous_fy_today_sales, 0 AS previous_fy_mtd_sales, 0 AS previous_fy_ytd_sales, 0 AS previous_fy_today_marketing_spend, 0 AS previous_fy_mtd_marketing_spend, 0 AS previous_fy_ytd_marketing_spend, 0 AS pmtd_sales, 0 AS pmtd_spend FROM thd-pharma-wh.MAPLEMONK.summary_dashboard_table_intermediate UNION ALL SELECT DATE_ADD(date, INTERVAL 1 YEAR) AS date, marketplace, channel_type, marketing_channel, brand, sub_category, 0 AS sales, 0 AS mtd_sales, 0 AS fy_ytd_sales, 0 AS marketing_Spend, 0 AS mtd_spend, 0 AS fy_ytd_spend, sales AS previous_fy_today_sales, mtd_sales AS previous_fy_mtd_sales, fy_ytd_sales AS previous_fy_ytd_sales, marketing_Spend AS previous_fy_today_marketing_spend, mtd_spend AS previous_fy_mtd_marketing_spend, fy_ytd_spend AS previous_fy_ytd_marketing_spend, 0 AS pmtd_sales, 0 AS pmtd_spend FROM thd-pharma-wh.MAPLEMONK.summary_dashboard_table_intermediate UNION ALL SELECT DATE_ADD(date, INTERVAL 1 MONTH) AS date, marketplace, channel_type, marketing_channel, brand, sub_category, 0 AS sales, 0 AS mtd_sales, 0 AS fy_ytd_sales, 0 AS marketing_Spend, 0 AS mtd_spend, 0 AS fy_ytd_spend, 0 AS previous_fy_today_sales, 0 AS previous_fy_mtd_sales, 0 AS previous_fy_ytd_sales, 0 AS previous_fy_today_marketing_spend, 0 AS previous_fy_mtd_marketing_spend, 0 AS previous_fy_ytd_marketing_spend, mtd_sales AS pmtd_sales, mtd_spend AS pmtd_spend FROM thd-pharma-wh.MAPLEMONK.summary_dashboard_table_intermediate ), aggregated AS ( SELECT date, marketplace, marketing_channel, brand, channel_type, sub_category, SUM(sales) AS sales, SUM(mtd_sales) AS mtd_sales, SUM(fy_ytd_sales) AS fy_ytd_sales, SUM(marketing_Spend) AS marketing_Spend, SUM(mtd_spend) AS mtd_spend, SUM(fy_ytd_spend) AS fy_ytd_spend, SUM(previous_fy_today_sales) AS previous_fy_today_sales, SUM(previous_fy_mtd_sales) AS previous_fy_mtd_sales, SUM(previous_fy_ytd_sales) AS previous_fy_ytd_sales, SUM(previous_fy_today_marketing_spend) AS previous_fy_today_marketing_spend, SUM(previous_fy_mtd_marketing_spend) AS previous_fy_mtd_marketing_spend, SUM(previous_fy_ytd_marketing_spend) AS previous_fy_ytd_marketing_spend, SUM(pmtd_sales) AS pmtd_sales, SUM(pmtd_spend) AS pmtd_spend FROM unid_data GROUP BY date, marketplace, marketing_channel, brand, channel_type, sub_category ) SELECT a.date, a.marketing_channel, a.marketplace, a.channel_type, a.brand, a.sub_category, a.sales, a.mtd_sales, a.fy_ytd_sales, a.marketing_Spend, a.mtd_spend, a.fy_ytd_spend, a.previous_fy_today_sales, a.previous_fy_mtd_sales, a.previous_fy_ytd_sales, a.previous_fy_today_marketing_spend, a.previous_fy_mtd_marketing_spend, a.previous_fy_ytd_marketing_spend, a.pmtd_sales, a.pmtd_spend, CASE WHEN a.date BETWEEN \'2026-04-01\' AND \'2027-03-31\' THEN (ct.sales_target / 365.0) / COUNT(*) OVER (PARTITION BY a.channel_type, a.brand, a.date) ELSE NULL END AS daily_channel_target, ct.sales_target AS year_target, ct.spends_target AS year_spend_target FROM aggregated a LEFT JOIN target_summary ct ON UPPER(a.channel_type) = UPPER(ct.channel) AND UPPER(a.brand) = UPPER(ct.brand) ORDER BY a.date DESC;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
